// Reads a lead CSV (e.g. Outscraper Google Maps export) and parses it into row objects.
// Expected columns: name, phone, city, state, address, website, email, reviews, rating, business_status, category
// Path comes from LEADS_CSV_PATH env var, defaults to ./leads.csv in the project root.

const fs = require('fs');
const path = require('path');

const csvPath = process.env.LEADS_CSV_PATH || path.join(process.cwd(), 'leads.csv');

if (!fs.existsSync(csvPath)) {
  throw new Error(`CSV not found at ${csvPath}. Set LEADS_CSV_PATH in .env or place leads.csv in the project root.`);
}

const raw = fs.readFileSync(csvPath, 'utf8');

function parseCsvRow(rowStr) {
  const values = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < rowStr.length; i++) {
    const c = rowStr[i];
    if (c === '"') {
      if (inQuotes && rowStr[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (c === ',' && !inQuotes) {
      values.push(current);
      current = '';
    } else {
      current += c;
    }
  }
  values.push(current);
  return values;
}

const lines = raw.split(/\r?\n/).filter(l => l.trim().length > 0);
const headers = parseCsvRow(lines[0]).map(h => h.trim().toLowerCase());

const rows = lines.slice(1).map(line => {
  const values = parseCsvRow(line);
  const row = {};
  headers.forEach((h, i) => { row[h] = (values[i] || '').trim(); });
  return row;
});

return rows.map(row => ({ json: row }));

// Maps Outscraper CSV columns into the pipeline's lead-record shape.
// Unlike the Apify path, leads with NO website are kept here — a missing
// website is the primary signal this campaign targets, not a reason to drop the lead.

const items = $input.all();

return items.map(item => {
  const row = item.json;

  const website = (row.website || '').trim();
  const email = (row.email || '').trim();
  const cityState = [row.city, row.state].filter(Boolean).join(', ');
  const address = [row.address, cityState].filter(Boolean).join(', ');

  return {
    json: {
      name: row.name || 'Unknown',
      website: website,
      address: address,
      rating: row.rating || '',
      phone: row.phone || '',
      category: row.category || '',
      business_status: row.business_status || '',
      reviews: row.reviews || '',
      email: email,
      status: email ? 'email_found' : 'scraped'
    }
  };
});

// Extract and clean lead data from Apify Google Maps results.
// Unlike the CSV path, this keeps leads with no website — the Apify path
// is for discovering a fresh city's full business universe, and a missing
// website here is exactly what we're looking for, same as the CSV path.

const items = $input.all();
const leads = [];

for (const item of items) {
  const data = item.json;

  leads.push({
    name: data.title || data.name || 'Unknown',
    website: data.website || data.url || '',
    address: data.address || data.street || '',
    rating: data.totalScore || data.rating || '',
    phone: data.phone || data.phoneUnformatted || '',
    category: data.categoryName || '',
    business_status: data.permanentlyClosed ? 'CLOSED' : 'OPERATIONAL',
    reviews: data.reviewsCount || '',
    email: '',
    status: 'scraped'
  });
}

return leads.map(lead => ({ json: lead }));

// Count total leads saved
const items = $input.all();
const count = items.length;
return [{ json: { message: `✅ Ingestion complete. ${count} leads saved to Google Sheets.`, leadsCount: count } }];

